// Кейс: .qa/tests/nusach-switch/NS-04-two-nusach-options.md.
import { expect } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, scrollToText } from '../../helpers/ui.ts';
import { shown, ensureNusach } from '../_lib/app-0710.ts';
import {
  goHome, openProfile, profileValue, withProfileNusach, openCatalogPrayer, shownNusach, nodes, button,
} from '../_lib/readiness-1910.ts';
import { NUSACH_ASHK, NUSACH_SFARAD, DESC_ASHK, DESC_SFARAD, NUSACH_GONE } from '../_lib/app-2110.ts';

async function checkProfileSheet(where: string) {
  await openProfile();
  await scrollToText('נוסח תפילה');
  await (await byLabelStartsWith('נוסח תפילה: ')).click();
  await (await byLabelStartsWith(NUSACH_ASHK)).waitForExist({ timeout: 15000 });
  const labels = (await nodes()).map((n) => n.label).join('\n');
  console.log(`[NS-04] ${where}: лист нусаха открыт`);
  expect(await (await byLabelStartsWith(NUSACH_SFARAD)).isExisting()).toBe(true);
  expect(labels).toContain(DESC_ASHK);
  expect(labels).toContain(DESC_SFARAD);
  for (const g of NUSACH_GONE) expect(labels).not.toContain(g);
  expect(labels).not.toContain('בקרוב');
  // Ровно 2 варианта: подписи, начинающиеся с «נוסח » и содержащие пояснение.
  const opts = (await nodes()).filter((n) => /^נוסח (אשכנז|ספרד)/.test(n.label) && /Button|Other|Cell/.test(n.type)).map((n) => n.label);
  expect(new Set(opts.map((o) => o.split(/[,.]/)[0])).size).toBe(2);
  await (await button('סגירה')).click().catch(() => {});
}
async function checkPrayerMenu() {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await (await byText('ספרדי')).waitForExist({ timeout: 10000 });
  await expect(byText('אשכנזי')).toBeExisting();
  expect(await shown(byTextContains('עדות המזרח'))).toBe(false);
  expect(await shown(byTextContains('בקרוב'))).toBe(false);
  await (await byLabelStartsWith('בחירת נוסח')).click();     // закрыть меню тем же заголовком
}

describe('21.10 — 2 нусаха (#24d9b5)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('NS-04a Профиль «נוסח תפילה»: ровно 2 варианта «נוסח אשכנז» / «נוסח ספרד / עדות המזרח» с пояснениями S-07, без «עדות המזרח · בקרוב» — при выбранном אשכנז и при выбранном ספרד; смена сохраняется и возвращается #24d9b5 #32e3cd9a S-07 AC3 F-46 AC2 AC4 @data', async () => {
    await openProfile();
    await scrollToText('נוסח תפילה');
    const orig = await profileValue('נוסח תפילה');
    await checkProfileSheet(`исходный «${orig}»`);
    const other = orig.includes('ספרד') ? 'אשכנז' : 'ספרד';
    await withProfileNusach(other, async () => {
      await checkProfileSheet(`после смены на «${other}»`);
      await goHome();
      await expect(byText(`נוסח ${other}`)).toBeExisting({ wait: 20000 });   // метка на главной (F-46 AC4)
    });
    await openProfile();
    await scrollToText('נוסח תפילה');
    expect(await profileValue('נוסח תפילה')).toBe(orig);
  });

  it('NS-04b Меню нусаха в молитве: 2 пункта «אשכנזי» / «ספרדי» (S-33), без «עדות המזרח, בקרוב» — из אשכנזי и из ספרדי; заголовок = показанный нусах; вернуть исходный #24d9b5 #32e3cd9a F-37 @prod-safe', async () => {
    await openCatalogPrayer('מנחה');
    const start = await shownNusach();
    await checkPrayerMenu();
    const other = start === 'אשכנזי' ? 'ספרדי' : 'אשכנזי';
    try {
      await ensureNusach(other);
      expect(await shownNusach()).toBe(other);
      await checkPrayerMenu();
    } finally {
      await ensureNusach(start as 'אשכנזי' | 'ספרדי');
    }
    expect(await shownNusach()).toBe(start);
  });
});
